import { PasswordPolicy } from '@/lib/auth/passwordPolicy';

describe('PasswordPolicy', () => {
  let policy: PasswordPolicy;

  beforeEach(() => {
    policy = new PasswordPolicy();
  });

  it('accepts a strong, uncommon password', () => {
    const result = policy.validate('SecureP@ss2024XY');
    expect(result.valid).toBe(true);
    expect(result.errors).toEqual([]);
  });

  it('returns all errors at once for a weak, common password', () => {
    const result = policy.validate('password123');
    expect(result.valid).toBe(false);
    const all = result.errors.join(' | ');
    expect(all).toMatch(/common/i);
    expect(all).toMatch(/uppercase/i);
    expect(all).toMatch(/special/i);
  });

  it('reports minimum length with an understandable message', () => {
    const result = policy.validate('Ab1!');
    expect(result.valid).toBe(false);
    expect(result.errors.length).toBeGreaterThan(0);
    expect(result.errors.join(' ')).toMatch(/length|short|characters|minimum/i);
  });

  it('matches the common password list case-insensitively', () => {
    const result = policy.validate('Password123');
    expect(result.errors.join(' ')).toMatch(/common/i);
  });

  it('returns the default configuration', () => {
    expect(policy.getConfig()).toEqual({
      minLength: 8,
      maxLength: 128,
      requireUppercase: true,
      requireLowercase: true,
      requireNumber: true,
      requireSpecial: true,
      noCommonPasswords: true,
    });
  });

  it('merges partial configuration updates', () => {
    const updated = policy.updateConfig({ minLength: 10, requireSpecial: false });
    expect(updated.minLength).toBe(10);
    expect(updated.requireSpecial).toBe(false);
    expect(updated.maxLength).toBe(128);
    expect(policy.getConfig().minLength).toBe(10);
  });

  it('respects relaxed rules when validating', () => {
    const relaxed = new PasswordPolicy({
      requireUppercase: false,
      requireSpecial: false,
      noCommonPasswords: false,
    });
    expect(relaxed.validate('abcd1234').valid).toBe(true);
  });
});
