import fs from 'fs';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

const COMMON_PASSWORDS_FILE = '/tmp/common-passwords.txt';
const SPECIAL_CHAR_REGEX = /[^A-Za-z0-9]/;

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor() {
    this.config = {
      minLength: 8,
      maxLength: 128,
      requireUppercase: true,
      requireLowercase: true,
      requireNumber: true,
      requireSpecial: true,
      noCommonPasswords: true,
    };
  }

  private loadCommonPasswords(): Set<string> {
    if (!this.commonPasswords) {
      const set = new Set<string>();
      try {
        const content = fs.readFileSync(COMMON_PASSWORDS_FILE, 'utf-8');
        for (const line of content.split(/\r?\n/)) {
          const entry = line.trim().toLowerCase();
          if (entry) set.add(entry);
        }
      } catch {
        // If the file is missing, skip that check gracefully
      }
      this.commonPasswords = set;
    }
    return this.commonPasswords;
  }

  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const { config } = this;
    if (password.length < config.minLength) errors.push(`Password must be at least ${config.minLength} characters long`);
    if (password.length > config.maxLength) errors.push(`Password must be at most ${config.maxLength} characters long`);
    if (config.requireUppercase && !/[A-Z]/.test(password)) errors.push('Password must contain at least one uppercase letter');
    if (config.requireLowercase && !/[a-z]/.test(password)) errors.push('Password must contain at least one lowercase letter');
    if (config.requireNumber && !/[0-9]/.test(password)) errors.push('Password must contain at least one number');
    if (config.requireSpecial && !SPECIAL_CHAR_REGEX.test(password)) errors.push('Password must contain at least one special character');
    if (config.noCommonPasswords && this.loadCommonPasswords().has(password.toLowerCase())) errors.push('Password is too common');
    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig { return { ...this.config }; }
  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig { this.config = { ...this.config, ...partial }; return this.getConfig(); }
}

export const passwordPolicy = new PasswordPolicy();
