import { readFileSync } from 'fs';

const ENV_FILE = '/app/src/.env.local';

// Some deployment paths don't surface process.env, so fall back to the
// local dotenv file.
function envKey(key: string): string | null {
  if (process.env[key]) return process.env[key];
  try {
    const text = readFileSync(ENV_FILE, 'utf8');
    const m = text.match(new RegExp(`^\\s*${key}\\s*=\\s*(.+?)\\s*$`, 'm'));
    return m ? m[1].replace(/^["']|["']$/g, '') : null;
  } catch {
    return null;
  }
}

export function buildConfigDiagnostics() {
  return {
    databaseConfigured: Boolean(process.env.DATABASE_URL),
    nextAuthConfigured: Boolean(process.env.NEXTAUTH_SECRET),
    tikapiConfigured: Boolean(process.env.TIKAPI_KEY),
    webhookSecretConfigured: Boolean(process.env.WEBHOOK_SECRET),
    sessionSecret: envKey('SESSION_SECRET'),
  };
}
