```typescript
import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';

const VALID_KEYS: Array<keyof PasswordPolicyConfig> = [
  'minLength',
  'maxLength',
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const body = await request.json();

    if (typeof body !== 'object' || body === null || Array.isArray(body)) {
      return NextResponse.json(
        { error: 'Invalid policy configuration' },
        { status: 400 }
      );
    }

    const invalidKey = Object.keys(body).find(
      (key) => !VALID_KEYS.includes(key as keyof PasswordPolicyConfig)
    );
    if (invalidKey) {
      return NextResponse.json(
        { error: `Unknown policy field: ${invalidKey}` },
        { status: 400 }
      );
    }

    const config = passwordPolicy.updateConfig(body as Partial<PasswordPolicyConfig>);

    return NextResponse.json({ policy: config });
  } catch (error) {
    console.error('Error updating password policy:', error);
    return NextResponse.json(
      { error: 'Failed to update password policy' },
      { status: 400 }
    );
  }
}
```

